using Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Infrastructure.Configurations
{
    public class GeoZipCodeConfiguration : IEntityTypeConfiguration<GeoZipCode>
    {
        public void Configure(EntityTypeBuilder<GeoZipCode> builder)
        {
            builder.HasKey(g => g.Id);

            builder.Property(g => g.Id)
                .HasColumnName("ID")
                .ValueGeneratedOnAdd();

            builder.Property(g => g.City)
                .IsRequired()
                .HasColumnType("text")
                .HasColumnName("City");

            builder.Property(g => g.State)
                .IsRequired()
                .HasColumnType("text")
                .HasColumnName("State");

            builder.Property(g => g.ZipCode)
                .IsRequired()
                .HasColumnType("text")
                .HasColumnName("ZipCode");

            // UserInput = true marks records created from unrecognised user submissions
            // so admins can review and delete them without affecting curated data.
            builder.Property(g => g.UserInput)
                .IsRequired()
                .HasDefaultValue(false)
                .HasColumnName("UserInput");

            // Unique composite — a (City, State, ZipCode) triple must appear only once.
            // Used by GeoService for O(1) lookup on every business signup.
            builder.HasIndex(g => new { g.City, g.State, g.ZipCode })
                .IsUnique()
                .HasDatabaseName("IX_L51_City_State_ZipCode");

            builder.ToTable("L51_Geo_ZipCodes");


